PRAGMA journal_mode=WAL;
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,password TEXT NOT NULL,settings TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS decks(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,description TEXT NOT NULL,kind TEXT NOT NULL,level TEXT NOT NULL,front TEXT NOT NULL,back TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notes(id TEXT PRIMARY KEY,deck_id TEXT NOT NULL REFERENCES decks(id) ON DELETE CASCADE,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cards(id TEXT PRIMARY KEY,note_id TEXT NOT NULL UNIQUE REFERENCES notes(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,schedule TEXT NOT NULL,due TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 0,revealed_version INTEGER);
CREATE TABLE IF NOT EXISTS reviews(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,card_id TEXT NOT NULL,rating INTEGER NOT NULL,reviewed_at TEXT NOT NULL,day TEXT NOT NULL,log TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attempts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,questions TEXT NOT NULL,answers TEXT,score INTEGER,created_at TEXT NOT NULL,completed_at TEXT,day TEXT);
CREATE INDEX IF NOT EXISTS card_due ON cards(user_id,due);
CREATE INDEX IF NOT EXISTS deck_owner ON decks(user_id);
CREATE INDEX IF NOT EXISTS review_day ON reviews(user_id,day);
CREATE INDEX IF NOT EXISTS attempts_owner ON attempts(user_id,completed_at);
